{
  "name": "mini-dns-service",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Mini DNS service API (Fastify)",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "dev": "node --watch src/server.js",
    "test": "node --test tests/*.test.js"
  },
  "engines": {
    "node": ">=20.11"
  },
  "dependencies": {
    "fastify": "^5.6.1"
  }
}

export const MIN_TTL_SECONDS = 1;
export const MAX_TTL_SECONDS = 86_400; // 24 hours
export const MAX_CNAME_CHAIN_DEPTH = 10;
export const MAX_HOSTNAME_LENGTH = 253;
export const MAX_LABEL_LENGTH = 63;

export const CLEANUP_INTERVAL_SECONDS = Number(process.env.DNS_CLEANUP_INTERVAL ?? 5);
export const PORT = Number(process.env.PORT ?? 8000);
export const HOST = process.env.HOST ?? "127.0.0.1";

export class DnsError extends Error {
  constructor(message, { statusCode = 400, errorCode = "DNS_ERROR", details } = {}) {
    super(message);
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.errorCode = errorCode;
    this.details = details ?? {};
  }

  toJSON() {
    const payload = {
      error: this.errorCode,
      message: this.message,
    };
    if (this.details && Object.keys(this.details).length > 0) {
      payload.details = this.details;
    }
    return payload;
  }
}

export class DnsValidationError extends DnsError {
  constructor(message, details) {
    super(message, { statusCode: 400, errorCode: "VALIDATION_ERROR", details });
  }
}

export class DnsNotFoundError extends DnsError {
  constructor(message, details) {
    super(message, { statusCode: 404, errorCode: "NOT_FOUND", details });
  }
}

export class DnsConflictError extends DnsError {
  constructor(message, details) {
    super(message, { statusCode: 409, errorCode: "CONFLICT", details });
  }
}

export class DnsCycleError extends DnsError {
  constructor(message, details) {
    super(message, { statusCode: 409, errorCode: "CNAME_CYCLE", details });
  }
}

export class DnsRecord {
  constructor({ hostname, type, value, createdAt, ttl = null, expiresAt = null }) {
    this.hostname = hostname;
    this.type = type;
    this.value = value;
    this.createdAt = createdAt;
    this.ttl = ttl ?? null;
    this.expiresAt = expiresAt ?? null;
  }

  isExpired(now = new Date()) {
    if (this.expiresAt == null) {
      return false;
    }
    return now.getTime() >= this.expiresAt.getTime();
  }

  toResponse() {
    return {
      hostname: this.hostname,
      type: this.type,
      value: this.value,
      createdAt: this.createdAt.toISOString(),
      ttl: this.ttl,
      expiresAt: this.expiresAt ? this.expiresAt.toISOString() : null,
    };
  }
}

import { MAX_HOSTNAME_LENGTH, MAX_LABEL_LENGTH } from "./config.js";
import { DnsValidationError } from "./errors.js";

const LABEL_RE = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;
const IPV4_RE =
  /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;

export function normalizeHostname(raw) {
  if (raw == null || !String(raw).trim()) {
    throw new DnsValidationError("Hostname is required.");
  }

  const hostname = String(raw).trim().replace(/\.+$/, "").toLowerCase();
  if (!hostname) {
    throw new DnsValidationError("Hostname is required.");
  }

  if (hostname.length > MAX_HOSTNAME_LENGTH) {
    throw new DnsValidationError(
      `Hostname exceeds maximum length of ${MAX_HOSTNAME_LENGTH} characters.`,
      { hostname, length: hostname.length },
    );
  }

  if (hostname.includes(" ")) {
    throw new DnsValidationError("Hostname must not contain spaces.", { hostname });
  }

  const labels = hostname.split(".");
  if (labels.some((label) => label === "")) {
    throw new DnsValidationError(
      "Hostname contains empty labels (consecutive or leading dots).",
      { hostname },
    );
  }

  for (const label of labels) {
    if (label.length > MAX_LABEL_LENGTH) {
      throw new DnsValidationError(
        `Hostname label '${label}' exceeds ${MAX_LABEL_LENGTH} characters.`,
        { hostname, label },
      );
    }
    if (!LABEL_RE.test(label)) {
      throw new DnsValidationError(
        "Hostname labels must start and end with an alphanumeric character and may contain hyphens in between (RFC 1123).",
        { hostname, label },
      );
    }
  }

  return hostname;
}

export function validateIpv4(raw) {
  if (raw == null || !String(raw).trim()) {
    throw new DnsValidationError("IPv4 address is required for A records.");
  }

  const value = String(raw).trim();
  if (!IPV4_RE.test(value)) {
    throw new DnsValidationError(`'${value}' is not a valid IPv4 address.`, { value });
  }

  return value;
}

export function validateRecordValue(recordType, value) {
  if (recordType === "A") {
    return validateIpv4(value);
  }
  if (recordType === "CNAME") {
    return normalizeHostname(value);
  }
  throw new DnsValidationError(
    `Unsupported record type '${recordType}'. Supported types: A, CNAME.`,
    { type: recordType },
  );
}

export function normalizeType(recordType) {
  const normalized = String(recordType ?? "").trim().toUpperCase();
  if (normalized !== "A" && normalized !== "CNAME") {
    throw new DnsValidationError(
      `Unsupported record type '${recordType}'. Supported types: A, CNAME.`,
      { type: recordType },
    );
  }
  return normalized;
}

export class DnsStore {
  constructor() {
    this._records = new Map();
  }

  now() {
    return new Date();
  }

  listFor(hostname, { includeExpired = false } = {}) {
    const records = [...(this._records.get(hostname) ?? [])];
    if (includeExpired) {
      return records;
    }
    const now = this.now();
    return records.filter((record) => !record.isExpired(now));
  }

  add(record) {
    const existing = this._records.get(record.hostname);
    if (existing) {
      existing.push(record);
    } else {
      this._records.set(record.hostname, [record]);
    }
    return record;
  }

  delete(hostname, recordType, value) {
    const records = this._records.get(hostname);
    if (!records) {
      return null;
    }

    const now = this.now();
    const index = records.findIndex(
      (record) =>
        !record.isExpired(now) && record.type === recordType && record.value === value,
    );
    if (index === -1) {
      return null;
    }

    const [removed] = records.splice(index, 1);
    if (records.length === 0) {
      this._records.delete(hostname);
    }
    return removed;
  }

  purgeExpired() {
    const now = this.now();
    let removed = 0;

    for (const [hostname, records] of this._records.entries()) {
      const kept = records.filter((record) => !record.isExpired(now));
      removed += records.length - kept.length;
      if (kept.length > 0) {
        this._records.set(hostname, kept);
      } else {
        this._records.delete(hostname);
      }
    }

    return removed;
  }

  clear() {
    this._records.clear();
  }
}

import { MAX_CNAME_CHAIN_DEPTH } from "./config.js";
import {
  DnsConflictError,
  DnsCycleError,
  DnsNotFoundError,
  DnsValidationError,
} from "./errors.js";
import { DnsRecord } from "./record.js";
import { normalizeHostname, normalizeType, validateRecordValue } from "./validators.js";

export class DnsService {
  constructor(store) {
    this.store = store;
  }

  addRecord(recordType, hostname, value, ttl = null) {
    hostname = normalizeHostname(hostname);
    recordType = normalizeType(recordType);
    value = validateRecordValue(recordType, value);

    if (recordType === "CNAME" && value === hostname) {
      throw new DnsCycleError("A CNAME record cannot point to itself.", {
        hostname,
        value,
      });
    }

    const existing = this.store.listFor(hostname);
    this._assertNoConflicts(hostname, recordType, value, existing);

    if (recordType === "CNAME") {
      this._assertNoCycle(hostname, value);
    }

    const now = new Date();
    const expiresAt = ttl != null ? new Date(now.getTime() + ttl * 1000) : null;
    const record = new DnsRecord({
      hostname,
      type: recordType,
      value,
      createdAt: now,
      ttl,
      expiresAt,
    });
    return this.store.add(record);
  }

  resolve(hostname) {
    hostname = normalizeHostname(hostname);
    const records = this.store.listFor(hostname);
    if (records.length === 0) {
      throw new DnsNotFoundError(`No DNS records found for hostname '${hostname}'.`, {
        hostname,
      });
    }

    const cname = findCname(records);
    if (cname) {
      const { resolvedIps } = this._followCnameChain(cname.value);
      return {
        hostname,
        resolvedIps,
        recordType: "CNAME",
        pointsTo: cname.value,
      };
    }

    return {
      hostname,
      resolvedIps: records.filter((record) => record.type === "A").map((record) => record.value),
      recordType: "A",
      pointsTo: null,
    };
  }

  listRecords(hostname) {
    hostname = normalizeHostname(hostname);
    const records = this.store.listFor(hostname);
    if (records.length === 0) {
      throw new DnsNotFoundError(`No DNS records found for hostname '${hostname}'.`, {
        hostname,
      });
    }
    return {
      hostname,
      records: records.map((record) => ({ type: record.type, value: record.value })),
    };
  }

  deleteRecord(hostname, recordType, value) {
    hostname = normalizeHostname(hostname);
    if (recordType == null || !String(recordType).trim()) {
      throw new DnsValidationError("Query parameter 'type' is required (A or CNAME).", {
        hostname,
      });
    }
    if (value == null || !String(value).trim()) {
      throw new DnsValidationError("Query parameter 'value' is required.", {
        hostname,
        type: recordType,
      });
    }

    recordType = normalizeType(recordType);
    value = validateRecordValue(recordType, value);

    const removed = this.store.delete(hostname, recordType, value);
    if (removed == null) {
      throw new DnsNotFoundError(
        `No ${recordType} record with value '${value}' found for '${hostname}'.`,
        { hostname, type: recordType, value },
      );
    }
    return removed;
  }

  purgeExpired() {
    return this.store.purgeExpired();
  }

  _assertNoConflicts(hostname, recordType, value, existing) {
    if (existing.length === 0) {
      return;
    }

    const existingTypes = new Set(existing.map((record) => record.type));

    if (existing.some((record) => record.type === recordType && record.value === value)) {
      throw new DnsConflictError(
        `Duplicate ${recordType} record for '${hostname}' with value '${value}'.`,
        { hostname, type: recordType, value },
      );
    }

    if (recordType === "CNAME") {
      throw new DnsConflictError(
        `Hostname '${hostname}' already has records; a CNAME cannot coexist with other records.`,
        { hostname, existingTypes: [...existingTypes].sort() },
      );
    }

    if (existingTypes.has("CNAME")) {
      throw new DnsConflictError(
        `Hostname '${hostname}' already has a CNAME record; A records cannot coexist with CNAME.`,
        { hostname, existingType: "CNAME" },
      );
    }
  }

  _assertNoCycle(hostname, target) {
    const seen = [hostname];
    let current = target;
    let depth = 0;

    while (current) {
      if (seen.includes(current)) {
        throw new DnsCycleError("CNAME record would create a circular reference.", {
          hostname,
          target,
          chain: [...seen, current].join(" -> "),
        });
      }
      if (depth >= MAX_CNAME_CHAIN_DEPTH) {
        throw new DnsCycleError(
          `CNAME chain exceeds maximum depth of ${MAX_CNAME_CHAIN_DEPTH}.`,
          { hostname, target, depth },
        );
      }

      seen.push(current);
      const records = this.store.listFor(current);
      const cname = findCname(records);
      if (cname == null) {
        return;
      }
      current = cname.value;
      depth += 1;
    }
  }

  _followCnameChain(start) {
    const seen = [];
    let current = start;
    let depth = 0;

    while (true) {
      if (seen.includes(current)) {
        throw new DnsCycleError("Circular CNAME reference detected during resolution.", {
          chain: [...seen, current].join(" -> "),
        });
      }
      if (depth >= MAX_CNAME_CHAIN_DEPTH) {
        throw new DnsCycleError(
          `CNAME chain exceeds maximum depth of ${MAX_CNAME_CHAIN_DEPTH}.`,
          { hostname: start, depth },
        );
      }

      seen.push(current);
      const records = this.store.listFor(current);
      if (records.length === 0) {
        return { resolvedIps: [], canonical: current };
      }

      const cname = findCname(records);
      if (cname) {
        current = cname.value;
        depth += 1;
        continue;
      }

      return {
        resolvedIps: records.filter((record) => record.type === "A").map((record) => record.value),
        canonical: current,
      };
    }
  }
}

function findCname(records) {
  return records.find((record) => record.type === "CNAME") ?? null;
}

function sleep(ms, signal) {
  return new Promise((resolve) => {
    if (signal?.aborted) {
      resolve();
      return;
    }

    const timer = setTimeout(resolve, ms);
    const onAbort = () => {
      clearTimeout(timer);
      resolve();
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

export async function ttlCleanupLoop(service, intervalSeconds, signal, logger) {
  if (intervalSeconds <= 0) {
    return;
  }

  logger?.info(`TTL cleanup loop started (interval=${intervalSeconds}s)`);

  while (!signal?.aborted) {
    await sleep(intervalSeconds * 1000, signal);
    if (signal?.aborted) {
      break;
    }

    const removed = service.purgeExpired();
    if (removed) {
      logger?.info(`TTL cleanup removed ${removed} expired record(s)`);
    }
  }

  logger?.info("TTL cleanup loop stopped");
}

import { MAX_TTL_SECONDS, MIN_TTL_SECONDS } from "./config.js";

export const errorResponseSchema = {
  type: "object",
  properties: {
    error: { type: "string" },
    message: { type: "string" },
    details: { type: "object" },
  },
  required: ["error", "message"],
};

const errorResponses = {
  400: { type: "object", properties: { error: { type: "string" }, message: { type: "string" } } },
  404: { type: "object", properties: { error: { type: "string" }, message: { type: "string" } } },
  409: { type: "object", properties: { error: { type: "string" }, message: { type: "string" } } },
};

export const addRecordSchema = {
  body: {
    type: "object",
    additionalProperties: false,
    required: ["type", "hostname", "value"],
    properties: {
      type: { type: "string", enum: ["A", "CNAME"] },
      hostname: { type: "string", minLength: 1, maxLength: 253 },
      value: { type: "string", minLength: 1, maxLength: 253 },
      ttl: { type: "integer", minimum: MIN_TTL_SECONDS, maximum: MAX_TTL_SECONDS },
    },
  },
  response: {
    201: {
      type: "object",
      properties: {
        hostname: { type: "string" },
        type: { type: "string" },
        value: { type: "string" },
        createdAt: { type: "string" },
        ttl: { type: ["integer", "null"] },
        expiresAt: { type: ["string", "null"] },
      },
    },
    ...errorResponses,
  },
};

export const hostnameParamsSchema = {
  type: "object",
  required: ["hostname"],
  properties: {
    hostname: { type: "string", minLength: 1 },
  },
};

export const resolveSchema = {
  params: hostnameParamsSchema,
  response: {
    200: {
      type: "object",
      properties: {
        hostname: { type: "string" },
        resolvedIps: { type: "array", items: { type: "string" } },
        recordType: { type: "string" },
        pointsTo: { type: ["string", "null"] },
      },
    },
    ...errorResponses,
  },
};

export const listRecordsSchema = {
  params: hostnameParamsSchema,
  response: {
    200: {
      type: "object",
      properties: {
        hostname: { type: "string" },
        records: {
          type: "array",
          items: {
            type: "object",
            properties: {
              type: { type: "string" },
              value: { type: "string" },
            },
          },
        },
      },
    },
    ...errorResponses,
  },
};

export const deleteRecordSchema = {
  params: hostnameParamsSchema,
  querystring: {
    type: "object",
    properties: {
      type: { type: "string" },
      value: { type: "string" },
    },
  },
  response: {
    200: {
      type: "object",
      properties: {
        message: { type: "string" },
        hostname: { type: "string" },
        type: { type: "string" },
        value: { type: "string" },
      },
    },
    ...errorResponses,
  },
};

import {
  addRecordSchema,
  deleteRecordSchema,
  listRecordsSchema,
  resolveSchema,
} from "../schemas.js";

export default async function dnsRoutes(fastify) {
  const { dnsService } = fastify;

  fastify.post("/api/dns", { schema: addRecordSchema }, async (request, reply) => {
    const { type, hostname, value, ttl = null } = request.body;
    const record = dnsService.addRecord(type, hostname, value, ttl ?? null);
    return reply.code(201).send(record.toResponse());
  });

  fastify.get(
    "/api/dns/:hostname/records",
    { schema: listRecordsSchema },
    async (request) => dnsService.listRecords(request.params.hostname),
  );

  fastify.get("/api/dns/:hostname", { schema: resolveSchema }, async (request) =>
    dnsService.resolve(request.params.hostname),
  );

  fastify.delete("/api/dns/:hostname", { schema: deleteRecordSchema }, async (request) => {
    const record = dnsService.deleteRecord(
      request.params.hostname,
      request.query.type,
      request.query.value,
    );
    return {
      message: "DNS record deleted.",
      hostname: record.hostname,
      type: record.type,
      value: record.value,
    };
  });
}

import Fastify from "fastify";

import { CLEANUP_INTERVAL_SECONDS } from "./config.js";
import { DnsError } from "./errors.js";
import dnsRoutes from "./routes/dns.js";
import { DnsService } from "./service.js";
import { DnsStore } from "./store.js";
import { ttlCleanupLoop } from "./ttlCleanup.js";

export async function buildApp({
  store,
  cleanupInterval,
  logger = true,
} = {}) {
  const dnsStore = store ?? new DnsStore();
  const dnsService = new DnsService(dnsStore);
  const interval =
    cleanupInterval === undefined ? CLEANUP_INTERVAL_SECONDS : cleanupInterval;

  const app = Fastify({
    logger,
    ajv: {
      customOptions: {
        removeAdditional: false,
        coerceTypes: false,
        allErrors: true,
      },
    },
  });

  app.decorate("dnsStore", dnsStore);
  app.decorate("dnsService", dnsService);

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof DnsError) {
      return reply.status(error.statusCode).send(error.toJSON());
    }

    if (error.validation || error.code === "FST_ERR_VALIDATION") {
      return reply.status(400).send({
        error: "VALIDATION_ERROR",
        message: "Request validation failed.",
        details: { errors: error.validation },
      });
    }

    request.log.error(error);
    return reply.status(500).send({
      error: "INTERNAL_ERROR",
      message: "An unexpected error occurred.",
    });
  });

  app.get("/health", async () => ({ status: "ok" }));

  await app.register(dnsRoutes);

  const abortController = new AbortController();
  let cleanupPromise = Promise.resolve();

  app.addHook("onReady", async () => {
    cleanupPromise = ttlCleanupLoop(dnsService, interval, abortController.signal, app.log);
  });

  app.addHook("onClose", async () => {
    abortController.abort();
    await cleanupPromise;
  });

  return app;
}

import { buildApp } from "./app.js";
import { HOST, PORT } from "./config.js";

const app = await buildApp();

try {
  await app.listen({ port: PORT, host: HOST });
} catch (error) {
  app.log.error(error);
  process.exit(1);
}

import assert from "node:assert/strict";
import { test } from "node:test";

import { DnsValidationError } from "../src/errors.js";
import { normalizeHostname, validateIpv4, validateRecordValue } from "../src/validators.js";

test("normalizeHostname lowercases and strips trailing dots", () => {
  assert.equal(normalizeHostname("Example.COM."), "example.com");
});

test("normalizeHostname rejects empty", () => {
  assert.throws(() => normalizeHostname("   "), DnsValidationError);
});

test("normalizeHostname rejects spaces", () => {
  assert.throws(() => normalizeHostname("exa mple.com"), /spaces/);
});

test("normalizeHostname rejects leading hyphen", () => {
  assert.throws(() => normalizeHostname("-example.com"), /RFC 1123/);
});

test("normalizeHostname rejects empty labels", () => {
  assert.throws(() => normalizeHostname("example..com"), /empty labels/);
});

test("normalizeHostname rejects overlong label", () => {
  const label = "a".repeat(64);
  assert.throws(() => normalizeHostname(`${label}.com`), /exceeds 63/);
});

test("normalizeHostname accepts a single label", () => {
  assert.equal(normalizeHostname("localhost"), "localhost");
});

test("validateIpv4 accepts a valid address", () => {
  assert.equal(validateIpv4("192.168.1.1"), "192.168.1.1");
});

test("validateIpv4 rejects out of range octets", () => {
  assert.throws(() => validateIpv4("192.168.1.256"), /not a valid IPv4/);
});

test("validateIpv4 rejects IPv6", () => {
  assert.throws(() => validateIpv4("2001:db8::1"), /not a valid IPv4/);
});

test("CNAME value must be a hostname", () => {
  assert.throws(() => validateRecordValue("CNAME", "not_a_hostname!"), DnsValidationError);
});

test("unknown record types are rejected", () => {
  assert.throws(() => validateRecordValue("MX", "mail.example.com"), /Unsupported/);
});

import assert from "node:assert/strict";
import { test } from "node:test";

import {
  DnsConflictError,
  DnsCycleError,
  DnsNotFoundError,
  DnsValidationError,
} from "../src/errors.js";
import { DnsService } from "../src/service.js";
import { DnsStore } from "../src/store.js";

function createService() {
  return new DnsService(new DnsStore());
}

test("multiple A records are allowed on one hostname", () => {
  const service = createService();
  service.addRecord("A", "example.com", "192.168.1.1");
  service.addRecord("A", "example.com", "192.168.1.2");
  const listed = service.listRecords("example.com");
  const values = listed.records.map((record) => record.value).sort();
  assert.deepEqual(values, ["192.168.1.1", "192.168.1.2"]);
});

test("duplicate A records are rejected", () => {
  const service = createService();
  service.addRecord("A", "example.com", "192.168.1.1");
  assert.throws(() => service.addRecord("A", "example.com", "192.168.1.1"), /Duplicate/);
});

test("duplicate detection is case-insensitive on hostname", () => {
  const service = createService();
  service.addRecord("A", "Example.COM", "10.0.0.1");
  assert.throws(() => service.addRecord("A", "example.com", "10.0.0.1"), DnsConflictError);
});

test("CNAME cannot coexist with A records", () => {
  const service = createService();
  service.addRecord("A", "example.com", "192.168.1.1");
  assert.throws(
    () => service.addRecord("CNAME", "example.com", "other.com"),
    /cannot coexist/,
  );
});

test("A records cannot coexist with a CNAME", () => {
  const service = createService();
  service.addRecord("CNAME", "alias.example.com", "example.com");
  assert.throws(
    () => service.addRecord("A", "alias.example.com", "192.168.1.1"),
    /already has a CNAME/,
  );
});

test("only one CNAME per hostname", () => {
  const service = createService();
  service.addRecord("CNAME", "alias.example.com", "example.com");
  assert.throws(
    () => service.addRecord("CNAME", "alias.example.com", "other.com"),
    DnsConflictError,
  );
});

test("self-referential CNAME is rejected", () => {
  const service = createService();
  assert.throws(
    () => service.addRecord("CNAME", "loop.example.com", "loop.example.com"),
    /cannot point to itself/,
  );
});

test("CNAME cycle is detected on insert", () => {
  const service = createService();
  service.addRecord("CNAME", "a.example.com", "b.example.com");
  service.addRecord("CNAME", "b.example.com", "c.example.com");
  assert.throws(
    () => service.addRecord("CNAME", "c.example.com", "a.example.com"),
    DnsCycleError,
  );
});

test("resolve returns all A record IPs", () => {
  const service = createService();
  service.addRecord("A", "example.com", "192.168.1.1");
  service.addRecord("A", "example.com", "192.168.1.2");
  const result = service.resolve("example.com");
  assert.equal(result.recordType, "A");
  assert.equal(result.pointsTo, null);
  assert.deepEqual([...result.resolvedIps].sort(), ["192.168.1.1", "192.168.1.2"]);
});

test("resolve follows a CNAME to A records", () => {
  const service = createService();
  service.addRecord("A", "example.com", "192.168.1.1");
  service.addRecord("A", "example.com", "192.168.1.2");
  service.addRecord("CNAME", "alias.example.com", "example.com");
  const result = service.resolve("alias.example.com");
  assert.equal(result.recordType, "CNAME");
  assert.equal(result.pointsTo, "example.com");
  assert.deepEqual([...result.resolvedIps].sort(), ["192.168.1.1", "192.168.1.2"]);
});

test("resolve follows a CNAME chain and reports the immediate target", () => {
  const service = createService();
  service.addRecord("A", "example.com", "10.0.0.1");
  service.addRecord("CNAME", "blog.example.com", "example.com");
  service.addRecord("CNAME", "www.example.com", "blog.example.com");
  const result = service.resolve("www.example.com");
  assert.equal(result.pointsTo, "blog.example.com");
  assert.deepEqual(result.resolvedIps, ["10.0.0.1"]);
});

test("dangling CNAME resolves to an empty IP list", () => {
  const service = createService();
  service.addRecord("CNAME", "alias.example.com", "missing.example.com");
  const result = service.resolve("alias.example.com");
  assert.deepEqual(result.resolvedIps, []);
  assert.equal(result.pointsTo, "missing.example.com");
});

