import assert from "node:assert/strict";
import { test } from "node:test";
import { setTimeout as delay } from "node:timers/promises";

import { DnsNotFoundError } from "../src/errors.js";
import { DnsService } from "../src/service.js";
import { DnsStore } from "../src/store.js";
import { ttlCleanupLoop } from "../src/ttlCleanup.js";

test("cleanup loop purges expired records", async () => {
  const service = new DnsService(new DnsStore());
  const record = service.addRecord("A", "expire.example.com", "10.0.0.9", 60);
  record.expiresAt = new Date(Date.now() - 1000);

  const abort = new AbortController();
  const loop = ttlCleanupLoop(service, 0.05, abort.signal);
  try {
    await delay(200);
    assert.throws(() => service.resolve("expire.example.com"), DnsNotFoundError);
  } finally {
    abort.abort();
    await loop;
  }
});

test("omitting ttl creates a non-expiring record", () => {
  const service = new DnsService(new DnsStore());
  const record = service.addRecord("A", "example.com", "192.168.0.1");
  assert.equal(record.ttl, null);
  assert.equal(record.expiresAt, null);
  assert.deepEqual(service.resolve("example.com").resolvedIps, ["192.168.0.1"]);
});

